@Mod.EventBusSubscriber(modid="thaumcraft")
public final class PechProbe {
    static final BlockPos PAD=new BlockPos(24008,160,8);
    static int stage,ticks,attempts;static ServerPlayer actor;static BlockPos forest;static Pech natural,cargo,walker;static Zombie victim;static final List<Zombie> spellTargets=new ArrayList<>();static float beforeHealth;
    static final List<Pech> pickupActors=new ArrayList<>();static final List<Pech> born=new ArrayList<>();static final List<ItemEntity> drops=new ArrayList<>();static final List<Arrow> arrows=new ArrayList<>();
    public static volatile boolean readyWorld,readyMenu,tradeDone;public static final List<UUID> viewIds=new ArrayList<>();
    static String mode(){return System.getProperty("thaumcraft.worldgenProbe","");}
    static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
    @SubscribeEvent public static void join(EntityJoinLevelEvent e){if(!mode().startsWith("pech"))return;if(e.getEntity() instanceof Pech p)born.add(p);if(e.getEntity() instanceof ItemEntity i)drops.add(i);if(e.getEntity() instanceof Arrow a)arrows.add(a);}
    @SubscribeEvent public static void login(net.minecraftforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent e){if(mode().equals("pech-client")&&e.getEntity() instanceof ServerPlayer p){actor=p;p.setGameMode(GameType.CREATIVE);p.setHealth(p.getMaxHealth());}}
    static ServerPlayer fake(ServerLevel l,String name){var p=new ServerPlayer(l.getServer(),l,new GameProfile(UUID.nameUUIDFromBytes(name.getBytes(java.nio.charset.StandardCharsets.UTF_8)),name),ClientInformation.createDefault());new net.minecraft.server.network.ServerGamePacketListenerImpl(l.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));p.setPos(Vec3.atCenterOf(PAD));p.getAbilities().invulnerable=true;p.setNoGravity(true);l.addNewPlayer(p);return p;}
    static Pech pech(ServerLevel l,BlockPos p,int variant){var w=new Pech(PechContent.PECH.get(),l);w.finalizeSpawn(l,l.getCurrentDifficultyAt(p),EntitySpawnReason.COMMAND,null);w.variant(variant);w.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(variant==1?thaumcraft.content.SimpleContent.ITEMS.get("pech_wand").get():variant==2?Items.BOW:Items.IRON_PICKAXE));w.setDropChance(EquipmentSlot.MAINHAND,variant==1?.1F:.2F);w.setPos(Vec3.atBottomCenterOf(p));w.setNoAi(true);w.setPersistenceRequired();check(l.addFreshEntity(w),"Could not add fixture pech");return w;}
    static ItemEntity item(ServerLevel l,Vec3 at,ItemStack stack){var e=new ItemEntity(l,at.x,at.y,at.z,stack);e.setNoPickUpDelay();check(l.addFreshEntity(e),"Could not add fixture item");return e;}
    static int count(Player p,Item item){int n=0;for(int i=0;i<p.getInventory().getContainerSize();i++)if(p.getInventory().getItem(i).is(item))n+=p.getInventory().getItem(i).getCount();return n;}
    static void force(ServerLevel l,BlockPos p){for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)l.setChunkForced((p.getX()>>4)+x,(p.getZ()>>4)+z,true);l.getChunk(p);}
    static void pad(ServerLevel l){force(l,PAD);for(int x=-12;x<=35;x++)for(int z=-10;z<=14;z++){l.setBlock(PAD.offset(x,-1,z),Blocks.GRASS_BLOCK.defaultBlockState(),2);for(int y=0;y<8;y++)l.setBlock(PAD.offset(x,y,z),Blocks.AIR.defaultBlockState(),2);}}
    static void rules(ServerLevel l){
        var types=new HashSet<Integer>();for(int i=0;i<200;i++){var p=new Pech(PechContent.PECH.get(),l);p.finalizeSpawn(l,l.getCurrentDifficultyAt(PAD),EntitySpawnReason.NATURAL,null);types.add(p.variant());check(p.getDropChances().byEquipment(EquipmentSlot.MAINHAND)==(p.variant()==1?.1F:.2F),"Wrong default equipment drop chance");}check(types.size()==3,"Missing randomized pech variant");
        for(int variant=0;variant<3;variant++){var offers=PechTrades.offers(l,variant);for(int rank=1;rank<=5;rank++){int r=rank;check(offers.stream().anyMatch(o->o.rank()==r),"Missing trade rank");}var sample=pech(l,PAD.east(variant*3),variant);var aspects=thaumcraft.research.AspectCatalog.entity(sample);check(aspects.getOrDefault("humanus",0)==10&&aspects.getOrDefault("permutatio",0)==10,"Pech aspects missing");sample.discard();}
        check(thaumcraft.research.AspectCatalog.triggers(true,"thaumcraft:pech").contains("!Pech"),"Pech scan trigger missing");
        var mage=pech(l,PAD,1);boolean wand=false;for(int i=0;i<1000;i++){var rolled=PechTrades.roll(l,mage,32);if(rolled.isPresent())wand|=rolled.get().outputs().stream().anyMatch(s->s.is(thaumcraft.content.SimpleContent.ITEMS.get("pech_wand").get()));}check(wand,"Wand never available from mage trades");mage.discard();
        var egg=new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("pech_spawn_egg").get());check(egg.get(DataComponents.ENTITY_DATA).type()==PechContent.PECH.get(),"Wrong spawn egg entity");
        Thaumcraft.LOGGER.info("PECH_RULES_OK: three native equipment variants, original drop chances, five ranks, mage wand, aspects, scan discovery, functional spawn egg");
    }
    static void inventories(ServerLevel l){
        var p=pech(l,PAD,0);actor.setPos(p.position().add(1,0,0));
        var gift=item(l,p.position(),new ItemStack(Items.ENDER_PEARL,3));check(p.collect(gift)&&p.friendly()&&gift.getItem().getCount()==2,"Gift did not consume exactly one to befriend");check(p.collect(gift)&&!gift.isAlive()&&p.pack.getItem(0).getCount()==2,"Friendly pack lost remaining gift items");
        for(int i=0;i<9;i++)p.pack.setItem(i,new ItemStack(Items.COBBLESTONE,64));p.pack.setItem(0,new ItemStack(Items.COBBLESTONE,63));var partial=item(l,p.position(),new ItemStack(Items.COBBLESTONE,4));check(p.collect(partial)&&partial.getItem().getCount()==3&&p.pack.getItem(0).getCount()==64,"Partial pickup lost or duplicated items");check(!p.collect(partial),"Full pack accepted more items");partial.discard();
        check(!p.removeWhenFarAway(100000),"Full pack can despawn");p.pack.clearContent();check(p.removeWhenFarAway(100000),"Empty pack never despawns");
        var excluded=item(l,p.position(),new ItemStack(Items.ENDER_PEARL));excluded.getPersistentData().putBoolean(Pech.RETURNED,true);check(!p.collect(excluded),"Pech reclaimed returned inventory");excluded.discard();
        actor.getInventory().clearContent();check(p.beginTrade(actor),"Could not start friendly trade");var menu=new PechMenu(1,actor.getInventory(),p);actor.containerMenu=menu;
        var other=fake(l,"PechOtherProbe");other.setPos(actor.position());check(!p.beginTrade(other),"Two simultaneous traders accepted");other.discard();
        p.escrow.setItem(0,new ItemStack(Items.COBBLESTONE,20));check(!menu.clickMenuButton(actor,0)&&p.escrow.getItem(0).getCount()==20,"Non-valued input consumed");
        p.escrow.setItem(0,new ItemStack(Items.ENDER_PEARL,12));p.escrow.setItem(1,new ItemStack(Items.DIRT));check(!menu.clickMenuButton(actor,0)&&p.escrow.getItem(0).getCount()==12,"Occupied output accepted another roll");check(!menu.slots.get(1).mayPlace(new ItemStack(Items.DIRT)),"Output slot accepts input");p.escrow.setItem(1,ItemStack.EMPTY);
        long tradeSeed=0;while(true){p.getRandom().setSeed(tradeSeed);if(PechTrades.roll(l,p,15).isPresent())break;tradeSeed++;}p.getRandom().setSeed(tradeSeed);check(menu.clickMenuButton(actor,0)&&p.escrow.getItem(0).getCount()==11,"Native menu did not pay one offering");check(!menu.clickMenuButton(actor,0)&&p.escrow.getItem(0).getCount()==11,"Duplicate same-tick roll consumed another offering");
        menu.removed(actor);actor.containerMenu=actor.inventoryMenu;check(p.escrow.isEmpty()&&count(actor,Items.ENDER_PEARL)==11,"Closing did not return exact unpaid offerings");menu.removed(actor);check(count(actor,Items.ENDER_PEARL)==11,"Repeated close duplicated offerings");
        p.friendly(true);for(int i=0;i<36;i++)actor.getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));check(p.beginTrade(actor),"Full inventory trade could not reopen");actor.containerMenu=new PechMenu(2,actor.getInventory(),p);p.escrow.setItem(0,new ItemStack(Items.ENDER_PEARL,5));p.escrow.setItem(1,new ItemStack(Items.DIAMOND,2));int firstDrop=drops.size();actor.containerMenu.removed(actor);actor.containerMenu=actor.inventoryMenu;check(p.escrow.isEmpty(),"Full inventory left unreturned escrow");var refunded=drops.subList(firstDrop,drops.size());check(refunded.stream().filter(e->e.getItem().is(Items.ENDER_PEARL)).mapToInt(e->e.getItem().getCount()).sum()==5&&refunded.stream().filter(e->e.getItem().is(Items.DIAMOND)).mapToInt(e->e.getItem().getCount()).sum()==2,"Full inventory refund lost items");check(refunded.stream().allMatch(e->e.getPersistentData().getBooleanOr(Pech.RETURNED,false)),"Refund items can be reclaimed by pech");refunded.forEach(Entity::discard);actor.getInventory().clearContent();
        p.friendly(true);actor.setPos(p.position().add(10,0,0));check(!p.beginTrade(actor),"Remote trade accepted");actor.setPos(p.position().add(1,0,0));p.discard();
        Thaumcraft.LOGGER.info("PECH_INVENTORY_OK: one-item befriending, exact pickup remainders, full bag, despawn rule, returned-item exclusion, single trader, native paid menu, output locks, replay rejection, exact close refund and range");
    }
    static void anger(ServerLevel l){var a=pech(l,PAD,0);var b=pech(l,PAD.east(3),1);a.friendly(true);b.friendly(true);actor.setGameMode(GameType.SURVIVAL);actor.getAbilities().invulnerable=true;check(a.hurtServer(l,actor.damageSources().playerAttack(actor),1),"Player hit rejected");check(a.anger()>=400&&a.anger()<800&&b.anger()>=400&&!a.friendly()&&!b.friendly(),"Group anger or friendship reset missing");actor.setGameMode(GameType.CREATIVE);var c=pech(l,PAD.east(6),0);c.friendly(true);c.hurtServer(l,actor.damageSources().playerAttack(actor),1);check(c.anger()==0&&c.friendly(),"Creative attack angered pech");a.discard();b.discard();c.discard();actor.setGameMode(GameType.SURVIVAL);Thaumcraft.LOGGER.info("PECH_ANGER_OK: 400..799 ticks, nearby group reaction, friendship cleared, creative exception");}
    static void loot(ServerLevel l){
        var at=PAD.east(25);force(l,at);var example=pech(l,at,1);
        var key=net.minecraft.resources.ResourceKey.create(Registries.LOOT_TABLE,thaumcraft.content.SimpleContent.id("entities/pech"));var table=l.getServer().reloadableRegistries().getLootTable(key);check(table!=net.minecraft.world.level.storage.loot.LootTable.EMPTY,"Pech loot table did not load");
        var params=new net.minecraft.world.level.storage.loot.LootParams.Builder(l).withParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.THIS_ENTITY,example).withParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.ORIGIN,example.position()).withParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.DAMAGE_SOURCE,actor.damageSources().playerAttack(actor)).withParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.ATTACKING_ENTITY,actor).withParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.LAST_DAMAGE_PLAYER,actor).create(net.minecraft.world.level.storage.loot.parameters.LootContextParamSets.ENTITY);
        int gold=0,knowledge=0;for(int n=0;n<4096;n++)for(var s:table.getRandomItems(params)){if(s.is(Items.GOLD_NUGGET))gold+=s.getCount();if(s.is(thaumcraft.infusion.CuriosityContent.CURIO.get())){check(thaumcraft.infusion.CuriosityContent.variant(s).equals("knowledge"),"Wrong curiosity loot component");knowledge++;}}
        check(gold>0&&knowledge>0,"Native gold/curiosity loot missing");example.discard();drops.clear();
        for(int n=0;n<128;n++){var p=pech(l,at,1);p.hurtServer(l,actor.damageSources().playerAttack(actor),1000);}
        check(drops.stream().anyMatch(e->e.getItem().is(Items.GOLD_NUGGET)),"Physical gold drops missing");check(drops.stream().anyMatch(e->e.getItem().is(thaumcraft.content.SimpleContent.ITEMS.get("pech_wand").get())),"Physical mage equipment drop missing");
        Thaumcraft.LOGGER.info("PECH_LOOT_OK: 4096 native loot rolls, {} gold nuggets, {} knowledge curiosities; physical gold and default-chance mage wand drops",gold,knowledge);
    }
    static void combat(ServerLevel l){for(int phase=0;phase<6;phase++){var p=pech(l,PAD.offset(phase*4,0,-6),0);p.tickCount=phase;p.setCanPickUpLoot(false);p.setNoAi(false);pickupActors.add(p);var gift=item(l,p.position(),new ItemStack(Items.ENDER_PEARL));gift.setNoGravity(true);gift.setDeltaMovement(Vec3.ZERO);}walker=pech(l,PAD,0);walker.friendly(true);walker.setNoAi(false);victim=new Zombie(EntityTypes.ZOMBIE,l);victim.setNoAi(true);victim.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.CARVED_PUMPKIN));victim.setPos(Vec3.atBottomCenterOf(PAD.east(5)));victim.setPersistenceRequired();l.addFreshEntity(victim);beforeHealth=victim.getHealth();walker.setTarget(victim);}
    static void ranged(ServerLevel l){check(pickupActors.stream().allMatch(Pech::friendly),"Pickup AI failed with staggered tick phases");pickupActors.forEach(Entity::discard);Thaumcraft.LOGGER.info("PECH_PICKUP_PHASES_OK: six real AI gift pickups with staggered tick phases and native equipment pickup disabled");check(victim.getHealth()<beforeHealth&&walker.distanceToSqr(Vec3.atBottomCenterOf(PAD))>1,"Melee AI did not navigate and damage target");walker.discard();victim.discard();
        victim=new Zombie(EntityTypes.ZOMBIE,l);victim.setNoAi(true);victim.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.CARVED_PUMPKIN));victim.setPos(Vec3.atBottomCenterOf(PAD.east(12)));victim.setPersistenceRequired();l.addFreshEntity(victim);beforeHealth=victim.getHealth();var archer=pech(l,PAD.east(5),2);archer.getMainHandItem().enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.FLAME),1);for(int i=0;i<48;i++)archer.performRangedAttack(victim,1);check(arrows.stream().anyMatch(a->a.getColor()!=-1),"Poisoned arrows absent");check(arrows.stream().anyMatch(Entity::isOnFire),"Native bow Flame enchantment missing");
        var mage=pech(l,PAD.east(6).south(4),1);for(int effect=0;effect<5;effect++){var bolt=new PechBolt(PechContent.BOLT.get(),l);bolt.setOwner(mage);bolt.effect(effect);bolt.setPos(mage.getEyePosition());var target=new Zombie(EntityTypes.ZOMBIE,l);target.setNoAi(true);target.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.CARVED_PUMPKIN));target.setPos(Vec3.atBottomCenterOf(PAD.east(14).south(-4+effect*4)));target.setPersistenceRequired();l.addFreshEntity(target);spellTargets.add(target);var d=target.getEyePosition().subtract(bolt.position());bolt.shoot(d.x,d.y,d.z,.75F,0);l.addFreshEntity(bolt);}Thaumcraft.LOGGER.info("PECH_MELEE_OK: actual navigation and native melee damage; ranged entities launched");
    }
    static BlockPos ground(ServerLevel l,BlockPos at){for(int dx=-64;dx<=64;dx+=2)for(int dz=-64;dz<=64;dz+=2){int x=at.getX()+dx,z=at.getZ()+dz;l.getChunk(x>>4,z>>4);for(int y=l.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,x,z);y>=l.getMinY();y--){var p=new BlockPos(x,y,z);if(l.getBiome(p).is(thaumcraft.worldgen.MagicalForest.KEY)&&l.getBlockState(p.below()).is(Blocks.GRASS_BLOCK)&&l.getBlockState(p).isAir()&&l.getBlockState(p.above()).isAir())return p;}}throw new AssertionError("No forest floor");}
    static void prepareNatural(ServerLevel l){forest=ground(l,WorldgenProbe.locate(l));force(l,forest);l.getEntitiesOfClass(Pech.class,new net.minecraft.world.phys.AABB(forest).inflate(32),Pech::isAlive).forEach(Entity::discard);var entries=l.getChunkSource().getGenerator().getMobsAt(l,l.structureManager(),MobCategory.MONSTER,forest).unwrap().stream().filter(e->e.value().type()==PechContent.PECH.get()).toList();check(entries.size()==1&&entries.getFirst().weight()==10&&entries.getFirst().value().count().minInclusive()==1&&entries.getFirst().value().count().maxInclusive()==1,"Wrong final pech spawn table");
        var crowd=new ArrayList<Pech>();for(int i=0;i<4;i++)crowd.add(pech(l,forest.east(i),0));var candidate=new Pech(PechContent.PECH.get(),l);candidate.setPos(Vec3.atBottomCenterOf(forest));check(!candidate.checkSpawnRules(l,EntitySpawnReason.NATURAL),"Local cap four ignored");crowd.removeLast().discard();check(candidate.checkSpawnRules(l,EntitySpawnReason.NATURAL),"Local cap never opens");crowd.forEach(Entity::discard);
        ThaumcraftConfig.allowSpawnPech.set(false);check(!candidate.checkSpawnRules(l,EntitySpawnReason.NATURAL),"Spawn option ignored");ThaumcraftConfig.allowSpawnPech.set(true);ThaumcraftConfig.wussMode.set(true);check(!candidate.checkSpawnRules(l,EntitySpawnReason.NATURAL),"Wuss spawn gate ignored");ThaumcraftConfig.wussMode.set(false);l.getServer().setDifficulty(Difficulty.PEACEFUL,true);check(!candidate.checkSpawnRules(l,EntitySpawnReason.NATURAL),"Peaceful spawn gate ignored");l.getServer().setDifficulty(Difficulty.NORMAL,true);
        actor.teleportTo(l,forest.getX()+40,forest.getY()+2,forest.getZ(),Set.of(),90,0,true);actor.setNoGravity(true);l.getServer().clockManager().setTotalTicks(l.dimensionType().defaultClock().orElseThrow(),18000);
        Thaumcraft.LOGGER.info("PECH_SPAWNING_RULES_OK: final weight 10/group one, native forest, cap four, disabled option, wuss and peaceful");
    }
    static void save(ServerLevel l){cargo=pech(l,PAD.south(8),1);cargo.friendly(true);for(int i=0;i<5;i++)cargo.pack.setItem(i,new ItemStack(Items.DIAMOND,i+1));actor.setPos(cargo.position().add(1,0,0));check(cargo.beginTrade(actor),"Could not reserve restart escrow");actor.containerMenu=new PechMenu(7,actor.getInventory(),cargo);cargo.escrow.setItem(0,new ItemStack(Items.ENDER_PEARL,3));cargo.escrow.setItem(1,new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("pech_wand").get()));try{Files.writeString(Path.of("pech54-proof.txt"),natural.getUUID()+","+natural.getX()+","+natural.getY()+","+natural.getZ()+","+cargo.getUUID());}catch(Exception e){throw new RuntimeException(e);}}
    static void read(ServerLevel l){try{var a=Files.readString(Path.of("pech54-proof.txt")).split(",");var at=BlockPos.containing(Double.parseDouble(a[1]),Double.parseDouble(a[2]),Double.parseDouble(a[3]));force(l,at);force(l,PAD);l.waitForEntities(new ChunkPos(at.getX()>>4,at.getZ()>>4),0);l.waitForEntities(new ChunkPos(PAD.getX()>>4,PAD.getZ()>>4),0);var wild=(Pech)l.getEntity(UUID.fromString(a[0]));cargo=(Pech)l.getEntity(UUID.fromString(a[4]));check(wild!=null&&wild.getSpawnReason()==EntitySpawnReason.NATURAL&&wild.friendly(),"Natural pech lost on restart");check(cargo!=null&&cargo.variant()==1&&cargo.pack.getItem(4).getCount()==5&&cargo.escrow.getItem(0).getCount()==3&&!cargo.escrow.getItem(1).isEmpty(),"Pack or escrow lost on restart");var other=fake(l,"PechOtherProbe");other.setPos(cargo.position());check(!cargo.beginTrade(other),"Another player stole saved escrow");other.discard();actor=fake(l,"PechMerchantProbe");actor.setPos(cargo.position().add(1,0,0));check(cargo.beginTrade(actor),"Owner could not recover escrow");var menu=new PechMenu(8,actor.getInventory(),cargo);actor.containerMenu=menu;menu.removed(actor);actor.containerMenu=actor.inventoryMenu;check(cargo.escrow.isEmpty()&&count(actor,Items.ENDER_PEARL)==3&&count(actor,thaumcraft.content.SimpleContent.ITEMS.get("pech_wand").get())==1,"Cold recovery lost or duplicated items");Thaumcraft.LOGGER.info("PECH_RESTART_OK: natural UUID/reason/friendship, variant, five pack slots, unpaid offering and reward, saved ownership, exact owner recovery while spawning disabled");}catch(Exception e){throw new RuntimeException(e);}}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post event){
        if(!mode().startsWith("pech")||stage==99)return;var l=event.server().overworld();ticks++;if(mode().equals("pech-client")&&stage>=5)for(var entity:l.getAllEntities())if(entity instanceof net.minecraft.world.entity.monster.Monster&&!(entity instanceof Pech))entity.discard();
        if(mode().equals("pech-read")){if(ticks<100)return;ThaumcraftConfig.allowSpawnPech.set(false);read(l);ThaumcraftConfig.allowSpawnPech.set(true);event.server().halt(false);stage=99;return;}
        if(stage==0){if(ticks<100||mode().equals("pech-client")&&actor==null)return;if(actor==null)actor=fake(l,"PechMerchantProbe");event.server().setDifficulty(Difficulty.NORMAL,true);if(!mode().equals("pech-client")){pad(l);rules(l);inventories(l);anger(l);loot(l);combat(l);stage=1;ticks=0;}else{savedClient(l);stage=5;ticks=0;}return;}
        if(stage==1){if(ticks<100)return;ranged(l);stage=2;ticks=0;return;}
        if(stage==2){if(ticks<80)return;check(victim.getHealth()<beforeHealth,"Ranged attacks never hit");check(spellTargets.getFirst().hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS)||spellTargets.getFirst().hasEffect(net.minecraft.world.effect.MobEffects.SLOWNESS),"Curse projectile did not apply effects");for(int n=1;n<5;n++)check(spellTargets.get(n).getHealth()<20,"Pech spell failed damage: "+n);spellTargets.forEach(Entity::discard);born.forEach(e->{if(e.isAlive())e.discard();});victim.discard();Thaumcraft.LOGGER.info("PECH_RANGED_OK: physical arrows, poison variants and five native projectile effects, actual target damage and curse");prepareNatural(l);stage=3;ticks=0;return;}
        if(stage==3){if(ticks==1){int allowed=0;for(int n=0;n<100;n++)if(Pech.placement(PechContent.PECH.get(),l,EntitySpawnReason.NATURAL,forest,l.getRandom()))allowed++;Thaumcraft.LOGGER.info("PECH_PLACEMENT_DIAGNOSTIC: floor {}, allowed {}/100, player distance {}",forest,allowed,actor.position().distanceTo(Vec3.atCenterOf(forest)));}var unwanted=new ArrayList<Entity>();for(var e:l.getAllEntities())if(e instanceof net.minecraft.world.entity.monster.Monster&&!(e instanceof Pech))unwanted.add(e);unwanted.forEach(Entity::discard);for(int i=0;i<8;i++)NaturalSpawner.spawnCategoryForPosition(MobCategory.MONSTER,l,forest);natural=born.stream().filter(p->!p.isRemoved()&&p.getSpawnReason()==EntitySpawnReason.NATURAL&&p.distanceToSqr(Vec3.atCenterOf(forest))<1600).findFirst().orElse(null);if(natural==null){check(++attempts<200,"No naturally selected pech");return;}natural.setPersistenceRequired();item(l,natural.position(),new ItemStack(Items.ENDER_PEARL));stage=4;ticks=0;Thaumcraft.LOGGER.info("PECH_NATURAL_OK: native weighted spawner, NATURAL reason, position {}, variant {}",natural.blockPosition(),natural.variant());return;}
        if(stage==4){if(!natural.friendly()){check(ticks<160,"Natural pech did not collect gift with real AI");return;}natural.setNoAi(true);natural.setDeltaMovement(Vec3.ZERO);Thaumcraft.LOGGER.info("PECH_NATURAL_PICKUP_OK: real AI collected a physical pearl and befriended the natural pech");if(!mode().equals("pech-client")){save(l);stage=99;event.server().halt(false);}else{scene(l);stage=5;ticks=0;}return;}
        if(stage==5){if(!Files.exists(Path.of("../work/pech54-open-menu")))return;actor.teleportTo(l,natural.getX()+2,natural.getY(),natural.getZ()+3,Set.of(),140,12,true);natural.interact(actor,InteractionHand.MAIN_HAND,Vec3.ZERO);check(actor.containerMenu instanceof PechMenu,"Native interaction did not open menu");natural.escrow.setItem(0,new ItemStack(Items.ENDER_PEARL,8));for(long seed=0;seed<10000;seed++){natural.getRandom().setSeed(seed);var rolled=PechTrades.roll(l,natural,15);if(rolled.isPresent()&&rolled.get().outputs().stream().anyMatch(s->!s.isEmpty())&&natural.getRandom().nextInt(100)>7){natural.getRandom().setSeed(seed);break;}}readyMenu=true;stage=6;Thaumcraft.LOGGER.info("PECH_CLIENT_MENU_READY: real entity interaction, eight physical offerings, seeded native roll ready");return;}
        if(stage==6&&natural.escrow.getItem(0).getCount()==7){check(natural.escrow.getItem(1).getCount()+natural.escrow.getItem(2).getCount()+natural.escrow.getItem(3).getCount()+natural.escrow.getItem(4).getCount()>0,"Paid trade produced no visible reward");tradeDone=true;stage=7;Thaumcraft.LOGGER.info("PECH_CLIENT_TRADE_OK: client button paid exactly one of eight offerings, authoritative rewards synchronized");}
    }
    static void savedClient(ServerLevel l){try{var a=Files.readString(Path.of("server/pech54-proof.txt")).split(",");var at=BlockPos.containing(Double.parseDouble(a[1]),Double.parseDouble(a[2]),Double.parseDouble(a[3]));force(l,at);l.waitForEntities(new ChunkPos(at.getX()>>4,at.getZ()>>4),0);natural=(Pech)l.getEntity(UUID.fromString(a[0]));check(natural!=null&&natural.friendly()&&natural.getSpawnReason()==EntitySpawnReason.NATURAL,"Saved natural showcase pech missing");scene(l);}catch(Exception e){throw new RuntimeException(e);}}
    static BlockPos nearGround(ServerLevel l,BlockPos at){for(int radius=0;radius<=6;radius++)for(int dx=-radius;dx<=radius;dx++)for(int dz=-radius;dz<=radius;dz++){int x=at.getX()+dx,z=at.getZ()+dz;l.getChunk(x>>4,z>>4);var p=new BlockPos(x,l.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,x,z),z);if(l.getBlockState(p.below()).is(Blocks.GRASS_BLOCK)&&l.getBlockState(p).isAir()&&l.getBlockState(p.above()).isAir()&&born.stream().noneMatch(e->e.isAlive()&&e.distanceToSqr(Vec3.atBottomCenterOf(p))<2))return p;}throw new AssertionError("No nearby showcase ground");}
    static void scene(ServerLevel l){viewIds.add(natural.getUUID());for(int v=0;v<3;v++)if(v!=natural.variant()){var at=nearGround(l,natural.blockPosition().offset(v==0?-3:3,0,0));var p=pech(l,at,v);p.friendly(true);viewIds.add(p.getUUID());}
        var view=natural.position().add(4,1,5);var delta=natural.position().add(0,1,0).subtract(view.add(0,1.62,0));float yaw=(float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),pitch=(float)-Math.toDegrees(Math.atan2(delta.y,Math.sqrt(delta.x*delta.x+delta.z*delta.z)));actor.teleportTo(l,view.x,view.y,view.z,Set.of(),yaw,pitch,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();actor.setNoGravity(true);actor.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.NIGHT_VISION,12000,0,false,false));l.getServer().clockManager().setTotalTicks(l.dimensionType().defaultClock().orElseThrow(),6000);readyWorld=true;Thaumcraft.LOGGER.info("PECH_CLIENT_WORLD_READY: natural befriended pech and two explicit variant fixtures, original model/textures/held equipment");}
}
